
/* Legacy visual donor: 7 original verified M7A atlases, embedded for an offline HTML.
 * Rendering fallback remains available if image decode is unavailable. */
(function(root){
  const data={"grass":"","earth":"","wood":"","stone":"","wall":"","warrior":"","rat":""};
  const out={};
  for(const [key,value] of Object.entries(data)){
    const img=new Image();img.decoding="async";img.src="data:image/png;base64,"+value;out[key]=img;
  }
  root.CoopegeB5Atlas=out;
})(globalThis);
